/* PortalFlow workspace: local-only adapters around the existing version/approval core. */
'use strict';
window.PF = (() => {
  const defaults = () => ({schemaVersion:2,brand:{name:'Northstar Studio',accent:'#7961d9',welcome:'A clearer way to work together.'},projectMeta:{},contacts:{},requestMeta:{},tasks:[],messages:[],comments:[],assets:[],invoices:[],timeEntries:[],services:[],documents:[],resources:[],activity:[],readActivity:[],onboarding:[],timer:null});
  const api = {views:{},actions:{},validators:[],projectSections:[],clientSections:[],deliverableSections:[],onChange:[],search:'',projectFilter:'active'};
  Object.defineProperties(api,{db:{get:()=>db},w:{get:()=>db.workspace}});
  Object.assign(api,{e,id:uid,now,date,button,field,heading,project,client,toast,go,render:()=>render(),form:openForm,
    area:(name,title,required=false,value='')=>`<label>${e(title)}<textarea name="${e(name)}" ${required?'required':''} maxlength="12000">${e(value)}</textarea></label>`,
    select:(name,title,options,value='')=>`<label>${e(title)}<select name="${e(name)}" aria-label="${e(title)}">${options.map(([id,text])=>`<option value="${e(id)}" ${String(id)===String(value)?'selected':''}>${e(text)}</option>`).join('')}</select></label>`,
    projectOptions:()=>db.projects.map(p=>[p.id,p.name]),clientOptions:()=>db.clients.map(c=>[c.id,c.name]),
    empty:text=>`<div class="empty">${e(text)}</div>`,money:(amount,currency='USD')=>new Intl.NumberFormat(undefined,{style:'currency',currency}).format(amount),
    change(fn,success='Saved in this demo'){const ok=commitChange(fn);render();if(ok&&success)toast(success);return ok},
    log(type,text,projectId='',clientId=''){db.workspace.activity.push({id:uid(),type,text,projectId,clientId,createdAt:now()});if(!api.shared?.active&&db.workspace.activity.length>500)db.workspace.activity.splice(0,db.workspace.activity.length-500)},
    download(filename,text,mime='text/plain'){const blob=new Blob([text],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},
    csvCell(value){let s=String(value??'');if(/^[\s]*[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'},
    safeUrl,defaults
  });
  const coreValidate=validate;
  validate=function(data){
    coreValidate(data);
    if(data.workspace===undefined)data.workspace=defaults();
    const w=data.workspace;
    if(!w||w.schemaVersion!==2||!w.brand||typeof w.brand.name!=='string'||w.brand.name.length>100||typeof w.brand.welcome!=='string'||!/^#[0-9a-f]{6}$/i.test(w.brand.accent))throw Error('Workspace branding is invalid.');
    for(const key of ['projectMeta','contacts','requestMeta'])if(!w[key]||typeof w[key]!=='object'||Array.isArray(w[key]))throw Error('Workspace metadata is invalid.');
    for(const key of ['tasks','messages','comments','assets','invoices','timeEntries','services','documents','resources','activity','readActivity','onboarding'])if(!Array.isArray(w[key]))throw Error('Workspace collection is invalid.');
    for(const key of ['tasks','messages','comments','assets','invoices','timeEntries','services','documents','resources','activity','onboarding'])if(w[key].some(x=>!x||typeof x.id!=='string')||new Set(w[key].map(x=>x.id)).size!==w[key].length)throw Error('Workspace records have invalid or duplicate IDs.');
    if(w.readActivity.some(x=>typeof x!=='string'))throw Error('Invalid activity read state.');
    for(const [id,m] of Object.entries(w.projectMeta))if(!data.projects.some(p=>p.id===id)||!m||typeof m.archived!=='boolean')throw Error('Invalid project state.');
    for(const [id,c] of Object.entries(w.contacts))if(!data.clients.some(x=>x.id===id)||!c||['phone','notes','contactName'].some(k=>typeof c[k]!=='string'))throw Error('Invalid client profile.');
    for(const r of w.resources)if(typeof r.title!=='string'||!data.clients.some(c=>c.id===r.clientId)||!safeUrl(r.url))throw Error('Invalid client resource.');
    for(const a of w.activity)if(['type','text','createdAt','projectId','clientId'].some(k=>typeof a[k]!=='string'))throw Error('Invalid activity record.');
    api.validators.forEach(check=>check(w,data));return data;
  };
  if(db.workspace===undefined)db.workspace=defaults();
  const coreCard=deliverableCard;
  deliverableCard=(d,isPortal)=>coreCard(d,isPortal)+api.deliverableSections.map(fn=>fn(d,isPortal)).join('');
  const coreDetail=detail;
  detail=()=>{const p=project(projectId);if(!p)return api.empty('Project not found.');return coreDetail()+`<div class="project-tools">${button('Edit project','pf-edit-project',p.id)}${button(db.workspace.projectMeta[p.id]?.archived?'Restore project':'Archive project','pf-archive',p.id)}</div>`+api.projectSections.map(fn=>`<section class="project-module">${fn(p)}</section>`).join('')};
  const corePortal=portal;
  portal=()=>{const html=corePortal();const c=client(portalClient);return html+(c?`<section class="card"><div class="eyebrow">YOUR WORKSPACE</div><h2>${e(db.workspace.brand.name)}</h2><p>${e(db.workspace.brand.welcome)}</p></section>`+api.clientSections.map(fn=>fn(c)).join('')+resources(c):'')};
  function resources(c){return `<section class="card client-section"><h2>Helpful resources</h2>${db.workspace.resources.filter(r=>r.clientId===c.id).map(r=>`<div class="row"><a href="${e(safeUrl(r.url))}" target="_blank" rel="noopener noreferrer">${e(r.title)} ↗</a></div>`).join('')||api.empty('No resources shared in this demo.')}</section>`}
  function activityRows(items){return items.map(a=>`<div class="activity-row"><span class="activity-dot"></span><div><b>${e(a.text)}</b><div class="meta">${e(date(a.createdAt))} · ${e(a.type)}</div></div></div>`).join('')||api.empty('Your workspace activity will appear here.');}
  api.views.dashboard={title:'Overview',icon:'◫',render(){
    const active=d=>!api.w.projectMeta[d.projectId]?.archived;
    const pending=db.deliverables.filter(d=>active(d)&&latest(d).status==='pending'),changes=db.deliverables.filter(d=>active(d)&&latest(d).status==='changes');
    return heading('Your workspace, in focus.','A clear next step for every client, project and review.',button('+ New project','new-project','',true))+`<div class="stats">${[['Active projects',db.projects.filter(p=>!api.w.projectMeta[p.id]?.archived).length],['Awaiting review',pending.length],['Changes requested',changes.length],['Open tasks',api.w.tasks.filter(t=>t.status!=='done').length]].map(([name,n])=>`<div class="card stat"><span class="meta">${name}</span><strong>${n}</strong></div>`).join('')}</div><section class="demo-guide card"><div><div class="eyebrow">TRY THE COMPLETE LOOP</div><h2>One draft. One decision. Everything in one place.</h2><p>Open work → preview client view → request changes → submit a new version → approve.</p></div>${db.projects.length?button('Try the sample workflow','project',db.projects[0].id,true):button('Create your first client','new-client','',true)}</section><div class="grid"><section><div class="section-heading"><h2>Projects in focus</h2>${button('View all','nav','projects')}</div><div class="list">${db.projects.filter(p=>!api.w.projectMeta[p.id]?.archived).slice(-4).reverse().map(projectCard).join('')||api.empty('Create a project to get started.')}</div></section><section class="card"><div class="section-heading"><h2>Review inbox</h2><span class="badge">${pending.length+changes.length}</span></div>${[...changes,...pending].slice(0,5).map(d=>`<div class="row"><div><b>${e(d.title)}</b><div class="meta">${e(project(d.projectId)?.name)} · v${latest(d).number}</div>${badge(latest(d).status)}</div>${button('Open','project',d.projectId)}</div>`).join('')||api.empty(db.deliverables.some(active)?'All caught up.':'No work has been submitted for review yet.')}<div class="section-heading space-top"><h2>Recent activity</h2>${button('View feed','nav','activity')}</div>${activityRows(api.w.activity.slice(-4).reverse())}</section></div><section class="card space-top"><h2>Latest client responses</h2>${approvalRows(db.approvals.slice(-4).reverse())}</section>`;
  }};
  api.views.projects={title:'Projects',icon:'▣',render(){const selected=api.projectFilter;const rows=db.projects.filter(p=>(selected==='archived')===!!api.w.projectMeta[p.id]?.archived);return heading('Projects','Keep briefs, versions and decisions together.',button('+ New project','new-project','',true))+`<div class="toolbar">${['active','archived'].map(s=>`<button data-action="pf-project-filter" data-id="${s}" class="${selected===s?'selected':''}">${s==='active'?'Active projects':'Archive'}</button>`).join('')}</div><div class="project-grid">${rows.map(projectCard).join('')||api.empty('No projects in this view.')}</div>`}};
  api.views.clients={title:'Clients',icon:'◎',render(){return clients()+`<div class="section-heading space-top"><h2>Client profiles & onboarding</h2></div><div class="project-grid">${db.clients.map(c=>{const m=api.w.contacts[c.id]||{};return `<section class="card"><h3>${e(c.name)}</h3><p>${e(m.contactName||'Add a named contact')} · ${e(m.phone||'No phone')}</p><p class="preserve-lines">${e(m.notes||'Keep client context and onboarding notes here.')}</p><div class="actions">${button('Edit profile','pf-client-profile',c.id)}${button('Edit client','pf-edit-client',c.id)}${button('Add resource','pf-resource',c.id)}</div></section>`}).join('')}</div>`}};
  api.views.activity={title:'Activity',icon:'◷',render(){return heading('Activity & notifications','A local workspace feed. No emails or push notifications are delivered.',button('Mark all read','pf-read-all'))+`<section class="card">${activityRows(api.w.activity.slice().reverse())}</section>`}};
  api.views.reports={title:'Reports',icon:'▥',render(){const all=db.deliverables.length,approved=db.deliverables.filter(d=>latest(d).status==='approved').length;const percent=all?Math.round(approved/all*100):0;return heading('Workspace reports','Calculated from this browser’s records, with no external analytics.')+`<div class="stats">${[['Clients',db.clients.length],['Projects',db.projects.length],['Approval decisions',db.approvals.length],['Time tracked (hours)',(api.w.timeEntries.reduce((n,t)=>n+t.minutes,0)/60).toFixed(1)]].map(([title,n])=>`<div class="card stat"><span class="meta">${title}</span><strong>${e(n)}</strong></div>`).join('')}</div><section class="card"><h2>Latest versions approved · ${percent}%</h2><div class="progress"><i style="width:${percent}%"></i></div><p>${approved} of ${all} deliverables. A new version starts a new review.</p></section>${api.commerceSummary?`<section class="card space-top"><h2>Invoice totals · manual records</h2><div class="table-wrap"><table><thead><tr><th>Currency</th><th>Draft</th><th>Issued / unpaid</th><th>Paid (manual)</th></tr></thead><tbody>${Object.entries(api.commerceSummary()).map(([currency,v])=>`<tr><td>${e(currency)}</td><td>${e(api.money(v.draft,currency))}</td><td>${e(api.money(v.issued,currency))}</td><td>${e(api.money(v.paid,currency))}</td></tr>`).join('')}</tbody></table></div></section>`:''}<section class="card space-top"><h2>Work by project</h2><div class="table-wrap"><table><thead><tr><th>Project</th><th>Client</th><th>Deliverables</th><th>Open tasks</th><th>Minutes</th></tr></thead><tbody>${db.projects.map(p=>`<tr><td>${e(p.name)}</td><td>${e(client(p.clientId)?.name)}</td><td>${db.deliverables.filter(d=>d.projectId===p.id).length}</td><td>${api.w.tasks.filter(t=>t.projectId===p.id&&t.status!=='done').length}</td><td>${api.w.timeEntries.filter(t=>t.projectId===p.id).reduce((n,t)=>n+t.minutes,0)}</td></tr>`).join('')}</tbody></table></div></section>`}};
  api.views.settings={title:'Settings',icon:'⚙',render(){return heading('Make it your workspace.','Branding, external resources and a portable backup of your local demo.')+`<div class="project-grid"><section class="card"><h2>Workspace branding</h2><p>Current studio: <b>${e(api.w.brand.name)}</b></p><p>Accent <span class="color-chip" style="background:${e(api.w.brand.accent)}"></span> ${e(api.w.brand.accent)}</p>${button('Edit branding','pf-brand','',true)}</section><section class="card"><h2>Backup & recovery</h2><p>Export before changing browsers or hosting domains. Imports are validated and replace this browser’s workspace after confirmation.</p><div class="actions">${button('Export backup','pf-backup')}${button('Import backup','pf-import')}</div></section><section class="card"><h2>Connected services</h2><p>No services are connected. Payments, secure accounts, shared files, email, e-signatures and API automation require real providers and a backend.</p><a href="research.html" target="_blank" rel="noopener">Competitor evidence & feature status ↗</a></section><section class="card"><h2>Privacy of this demo</h2><p>Client switching simulates a role. Anyone using this browser profile can inspect all records. Keep sensitive client information out of the demo.</p><p>Use one active editing tab. Clearing browser data clears this workspace.</p></section></div>`}};
  api.views.search={title:'Search results',icon:'⌕',hidden:true,render(){const q=api.search.toLowerCase();const match=x=>JSON.stringify(x).toLowerCase().includes(q);return heading('Search results',`Results for “${api.search}” in this local workspace.`)+`<section class="card"><h2>Projects</h2>${db.projects.filter(match).map(p=>`<div class="row"><b>${e(p.name)}</b>${button('Open project','project',p.id)}</div>`).join('')||api.empty('No projects match.')}<h2 class="space-top">Clients</h2>${db.clients.filter(match).map(c=>`<div class="row"><b>${e(c.name)}</b>${button('Preview client view','open-portal',c.id)}</div>`).join('')||api.empty('No clients match.')}<h2 class="space-top">Work, requests & tasks</h2>${[...db.deliverables,...db.requests,...api.w.tasks].filter(match).map(x=>`<div class="row"><div><b>${e(x.title)}</b><p>${e(x.note||'')}</p></div>${x.projectId?button('Open project','project',x.projectId):button('Requests','nav','requests')}</div>`).join('')||api.empty('No work matches.')}</section>`}};
  api.actions['pf-project-filter']=b=>{api.projectFilter=b.dataset.id;render()};
  api.actions['pf-archive']=b=>api.change(()=>{const p=project(b.dataset.id);if(!p)throw Error('Project not found.');const archived=!api.w.projectMeta[p.id]?.archived;api.w.projectMeta[p.id]={archived};api.log('project',`${archived?'Archived':'Restored'} ${p.name}`,p.id,p.clientId)});
  api.actions['pf-edit-project']=b=>{const p=project(b.dataset.id);if(!p)return;api.form('Edit project',field('name','Project name','text',p.name)+api.area('brief','Project brief',false,p.brief)+field('due','Due date','date',p.due,false)+field('payment','External payment link','url',p.payment,false),f=>{const live=project(b.dataset.id);if(!live)throw Error('Project not found.');live.name=clean(f.name);live.brief=f.brief.trim();live.due=f.due;live.payment=safeUrl(f.payment);api.log('project',`Updated ${live.name}`,live.id,live.clientId)})};
  api.actions['pf-edit-client']=b=>{const c=client(b.dataset.id);if(!c)return;api.form('Edit client',field('name','Client name','text',c.name)+field('email','Email (no email sent)','email',c.email),f=>{const live=client(b.dataset.id);if(!live)throw Error('Client not found.');live.name=clean(f.name);live.email=clean(f.email);api.log('client',`Updated ${live.name}`,'',live.id)})};
  api.actions['pf-client-profile']=b=>{const c=client(b.dataset.id),m=api.w.contacts[c.id]||{};api.form('Client profile',field('contactName','Contact name','text',m.contactName||'',false)+field('phone','Phone','tel',m.phone||'',false)+api.area('notes','Client notes',false,m.notes||''),f=>{api.w.contacts[c.id]={contactName:f.contactName.trim(),phone:f.phone.trim(),notes:f.notes.trim()};api.log('client',`Updated profile for ${c.name}`,'',c.id)})};
  api.actions['pf-resource']=b=>api.form('Add client resource',field('title','Resource title')+field('url','HTTP/HTTPS resource link','url'),f=>{if(!client(b.dataset.id))throw Error('Client not found.');api.w.resources.push({id:uid(),clientId:b.dataset.id,title:clean(f.title),url:safeUrl(f.url)});api.log('resource','Added a client resource','',b.dataset.id)});
  api.actions['pf-read-all']=()=>api.change(()=>api.w.readActivity=api.w.activity.map(a=>a.id),'Activity marked read');
  api.actions['pf-brand']=()=>api.form('Workspace branding',field('name','Studio name','text',api.w.brand.name)+field('accent','Accent colour','color',api.w.brand.accent)+api.area('welcome','Client welcome',false,api.w.brand.welcome),f=>{const name=clean(f.name);if(name.length>100)throw Error('Studio name must be 100 characters or fewer.');api.w.brand={name,accent:f.accent,welcome:f.welcome.trim()};api.log('settings','Updated workspace branding')});
  api.actions['pf-backup']=()=>api.download('portalflow-backup.json',JSON.stringify({format:'portalflow-backup',version:2,exportedAt:now(),data:db},null,2),'application/json');
  api.actions['pf-import']=()=>api.form('Import workspace backup',`<p>This replaces this browser’s workspace. Export your current backup first.</p>`+'<label>Load a backup file<input type="file" id="pf-backup-file" accept="application/json,.json"></label><label>Backup JSON<textarea name="backup" required maxlength="16000000"></textarea></label>'+field('confirm','Type REPLACE to confirm'),f=>{if(f.confirm!=='REPLACE')throw Error('Type REPLACE to confirm.');let backup;try{backup=JSON.parse(f.backup)}catch{throw Error('The backup is not valid JSON.')}if(backup.format!=='portalflow-backup'||backup.version!==2)throw Error('Unsupported backup format.');const next=validate(backup.data);db=next;api.log('backup','Imported validated workspace backup');view='dashboard';projectId=null});
  const coreCommit=commitChange;
  commitChange=function(change){
    const previous={clients:db.clients.length,projects:db.projects.length,work:db.deliverables.length,decisions:db.approvals.length,requests:db.requests.length,versions:db.deliverables.reduce((n,d)=>n+d.versions.length,0),activity:api.w.activity.length};
    return coreCommit(()=>{change();if(api.w.activity.length!==previous.activity)return;
      if(db.approvals.length>previous.decisions){const a=db.approvals.at(-1),d=db.deliverables.find(d=>d.id===a.deliverableId);api.log('approval',`${label(a.status)}: ${d?.title||'Work'} · v${a.number}`,d?.projectId||'');}
      else if(db.deliverables.reduce((n,d)=>n+d.versions.length,0)>previous.versions)api.log('review','Work version added for review');
      else if(db.projects.length>previous.projects)api.log('project','Project created',db.projects.at(-1).id,db.projects.at(-1).clientId);
      else if(db.clients.length>previous.clients)api.log('client','Client created','',db.clients.at(-1).id);
      else if(db.requests.length>previous.requests)api.log('request','Client request saved','',db.requests.at(-1).clientId);
    });
  };
  api.onChange.push(event=>{if(event.target.id!=='pf-backup-file')return;const file=event.target.files[0];if(!file)return;if(file.size>12000000){toast('Backup files must be under 12 MB.');return}const reader=new FileReader();reader.onload=()=>{if(modal.open){const input=modal.querySelector('[name="backup"]');if(input)input.value=String(reader.result)}};reader.onerror=()=>toast('Unable to read this backup file.');reader.readAsText(file)});
  api.start=()=>{
    try{validate(db);if(!storageBlocked)save()}catch{storageBlocked=true;db=demo();db.workspace=defaults();storageMessage('The extended workspace is invalid. Stored data is preserved. Recover a backup or use a fresh browser profile; this preview cannot save.');}
    render=function(){
      const entries=[['dashboard','Overview'],['projects','Projects'],['requests','Requests'],['tasks','Tasks'],['files','Files'],['clients','Clients'],['messages','Messages'],['billing','Invoices'],['time','Time tracking'],['services','Services'],['documents','Proposals'],['history','Approval history'],['reports','Reports'],['activity','Activity'],['portal','Client preview'],['pricing','Plan & pricing'],['settings','Settings']];
      document.querySelector('#nav').innerHTML=entries.filter(([id])=>api.views[id]||['history','portal'].includes(id)).map(([id,title])=>`<button data-action="nav" data-id="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}><span aria-hidden="true">${api.views[id]?.icon||'↗'}</span>${title}${id==='activity'&&api.w.activity.some(a=>!api.w.readActivity.includes(a.id))?'<i class="unread-dot"></i>':''}</button>`).join('');
      document.querySelector('#breadcrumb').textContent=view==='detail'?'Projects / '+(project(projectId)?.name||'Project'):api.views[view]?.title||({portal:'Client view preview',history:'Approval history'}[view]||'Workspace');
      document.documentElement.style.setProperty('--brand',api.w.brand.accent);document.querySelector('.aside-foot').innerHTML=`<div class="eyebrow">YOUR STUDIO</div><b>${e(api.w.brand.name)}</b><p>Browser-local demo</p><a href="research.html" target="_blank" rel="noopener">Feature evidence ↗</a>`;
      main.innerHTML=api.views[view]?api.views[view].render():({detail,history:approvalHistory,portal}[view]||api.views.dashboard.render)();
    };
    const header=document.querySelector('.top .actions');const search=document.createElement('form');search.id='pf-search-form';search.className='search-form';search.innerHTML='<label class="sr-only" for="pf-search">Search workspace</label><input id="pf-search" type="search" placeholder="Search your workspace…" maxlength="200"><button type="submit" aria-label="Run search">⌕</button>';header.prepend(search);search.onsubmit=event=>{event.preventDefault();const q=search.querySelector('input').value.trim();if(q){api.search=q;go('search')}};
    document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const fn=api.actions[b.dataset.action];if(fn)try{fn(b)}catch(err){toast(err.message)}});
    document.addEventListener('change',event=>{api.onChange.forEach(fn=>{try{fn(event)}catch(err){toast(err.message)}})});
    render();
  };
  return api;
})();
